const edition = globalThis.makeSubjectEdition({"year":2020,"grade":"9-11","tasksFile":"ZR_1920_quest_Standard_9-11.pdf","answersFile":"reviewed-9-11.pdf","title":"Эрмитаж","subject":"golden-fleece","contest":"Золотое руно","letters":"ABCD","count":45,"language":"ru","points":3,"sourceFile":"sources/golden-fleece/2020/9-11.json","sections":[{"start":1,"title":"История"},{"start":16,"title":"Коллекция"},{"start":31,"title":"Отражения"}],"reviewedKey":true}, [{"title":"Третий Зимний дворец","question":"Для этой императрицы в 30-х годах XVIII века архитектором Ф. Б. Растрелли был возведён Третий Зимний дворец.","choices":["Екатерина I","Елизавета Петровна","Анна Иоанновна","Екатерина II"],"answer":2,"steps":["Анна Иоанновна поручила Растрелли устроить более вместительную резиденцию в Петербурге.","Этот дворец предшествовал нынешнему Зимнему, который строили уже для Елизаветы."]},{"title":"Покои к свадьбе","question":"Этим зодчим по заказу Екатерины II было выполнено внутреннее убранство великокняжеских покоев в качестве подарка к бракосочетанию её старшего внука.","choices":["Ю. М. Фельтен","К. Росси","И. Е. Старов","Дж. Кваренги"],"answer":2,"steps":["Старшим внуком Екатерины II был Александр Павлович.","Работы по устройству великокняжеских покоев связаны с архитектором Иваном Старовым."]},{"title":"Зал для церемонии","question":"В этом зале Зимнего дворца Павел I был провозглашен великим магистром Мальтийского ордена.","choices":["Петровский","Гербовый","Фельдмаршальский","Георгиевский"],"answer":3,"steps":["Георгиевский зал служил Большим тронным залом Зимнего дворца.","Там проводили важные государственные церемонии, в том числе провозглашение Павла великим магистром."]},{"title":"Здание военного училища","question":"В этом эрмитажном здании в бытность его кадетским корпусом учились поэты-декабристы К. Ф. Рылеев и Ф. Н. Глинка.","choices":["Меншиковский дворец","Эрмитажный театр","Главный штаб","Зимний дворец"],"answer":0,"steps":["Меншиковский дворец отвели под Шляхетский кадетский корпус.","Это учебное заведение связывает здание с биографиями будущих литераторов и военных."]},{"title":"Начало собрания золота","question":"Первые экспонаты эрмитажной коллекции скифского золота были собраны по инициативе…","choices":["Петра I","Екатерины II","Л. А. Орбели","И. Е. Забелина"],"answer":0,"steps":["Пётр I распорядился сохранять старинные драгоценные находки из курганов.","Эти предметы заложили основу Сибирской коллекции и собрания древнего золота."]},{"title":"Первая постановка","question":"Первое представление этой пьесы состоялось на сцене Эрмитажного театра.","choices":["«Женитьба» Н. В. Гоголя","«Царь Борис» А. К. Толстого","«Саломея» О. Уайльда","«Царь Иудейский» К. К. Романова"],"answer":3,"steps":["Великий князь Константин Константинович Романов писал пьесы под инициалами К.","Р.","Его драму «Царь Иудейский» впервые поставили в Эрмитажном театре."]},{"title":"Помещения для нужд двора","question":"В царствование Николая II Большой Итальянский просвет периодически использовался для устройства…","choices":["лазарета","столов карточной игры","передвижных кухонь","библиотеки"],"answer":2,"steps":["Высокие Итальянские просветы могли временно использовать для задач, не связанных с выставками.","При Николае II там размещали передвижные кухни во время дворцовых мероприятий."]},{"title":"Вид после пожара","question":"Эта картина В. С. Садовникова была создана …","choices":["в подарок королеве Виктории","по заказу Екатерины II","после пожара в Зимнем дворце в 1837 году","в начале февральской революции 1917 года"],"answer":2,"steps":["Василий Садовников известен точными видами петербургских зданий.","На картине о Зимнем дворце он показал его после пожара 1837 года."],"figure":{"src":"assets/golden-fleece/2020/lessons/9-11/8.webp","alt":"Площадь перед протяжённым дворцовым фасадом","width":211,"height":139}},{"title":"Ранний собиратель Гогена","question":"Этот коллекционер первым в России стал покупать работы П. Гогена («Пирога» и «Пейзаж с двумя козами»).","choices":["И. А. Морозов","М. А. Морозов","С. И. Щукин","П. И. Щукин"],"answer":1,"steps":["Михаил Морозов начал покупать произведения современных французских художников.","Среди его покупок были работы Поля Гогена, позднее вошедшие в музейные собрания."]},{"title":"Праздник после мира","question":"Недельный маскарад в Меншиковском дворце проходил в честь …","choices":["основания Санкт-Петербурга","Ништадтского мира","свадьбы Анны Иоанновны","свадьбы Петра I и Екатерины I"],"answer":1,"steps":["Ништадтский мир завершил Северную войну и закрепил новые владения России на Балтике.","Долгую войну и её окончание отмечали придворными празднествами."]},{"title":"Предмет из частного собрания","question":"Этот сосуд оказался в Эрмитаже благодаря коллекционеру А. П. Базилевскому.","choices":["Колыванская ваза","Гидрия Царица ваз","Ваза Фортуни","Чертомлыкская амфора"],"answer":2,"steps":["Александр Базилевский собрал значительное собрание средневекового искусства.","В него входила ваза Фортуни с орнаментом испано-мавританской керамики."]},{"title":"Экскурсия без картин","question":"Научный сотрудник Эрмитажа П. Ф. Губчевский провёл несколько экскурсий «по пустым рамам» музея во время…","choices":["Первой мировой войны","Гражданской войны","распродажи эрмитажной коллекции 1929–1934 гг.","Блокады Ленинграда"],"answer":3,"steps":["В начале войны самые ценные картины эвакуировали, оставив на стенах рамы.","Во время блокады Павел Губчевский рассказывал по этим рамам о вывезенных произведениях."]},{"title":"Как учился художник","question":"Этот художник устроился в Эрмитаж чернорабочим и имел возможность совершенствовать свое искусство, копируя картины старых мастеров.","choices":["О. Н. Целков","М. М. Шемякин","Э. И. Неизвестный","О. Е. Григорьев"],"answer":1,"steps":["Михаил Шемякин работал в Эрмитаже, выполняя обязанности чернорабочего.","Возможность изучать и копировать картины помогала ему развиваться как художнику."]},{"title":"Ранние фотокопии","question":"Фотокопирование эрмитажных картин впервые было сделано …","choices":["при Александре II","после революции 1917 года","при Николае I","при Николае II"],"answer":0,"steps":["Систематическое фотографирование картин стало возможно после распространения фотографии в XIX веке.","Первые эрмитажные копии относятся ко времени Александра II."]},{"title":"Зимняя забава","question":"Катальные горки для великих князей в 80-е годы XVIII века устраивались…","choices":["рядом с Висячим садом","во дворе Зимнего дворца","во дворах Главного штаба","в Манеже"],"answer":0,"steps":["Сады и крытые переходы Малого Эрмитажа использовали по-разному в зависимости от сезона.","Катальные горки для князей устраивали около Висячего сада."]},{"title":"Плитки в интерьере","question":"Уникальный плафон Варварина покоя Меншиковского дворца декорирован голландской плиткой с изображением…","choices":["тюльпанов","обитателей моря","зайцев","амуров"],"answer":1,"steps":["В Меншиковском дворце стены и потолки украшали привозными голландскими плитками.","Морские существа среди их изображений напоминают об интересе эпохи к морю."]},{"title":"Цвет фигур на вазе","question":"Эта пелика работы мастера конца VI века до н. э. Евфрония создана в технике…","choices":["краснофигурная вазопись","чернофигурная вазопись","клазоменская вазопись","гнафия"],"answer":0,"steps":["На сосуде светлые красноватые фигуры оставлены цвета глины, а фон закрашен тёмным.","Так работает краснофигурная техника."],"figure":{"src":"assets/golden-fleece/2020/lessons/9-11/17.webp","alt":"Глиняный сосуд с двумя ручками и фигурной росписью","width":133,"height":194}},{"title":"Отдел и собрание","question":"Коллекция А. Д. Ланского входит в собрание этого старейшего отдела Государственного Эрмитажа.","choices":["Отдел Востока","Отдел археологии","Отдел нумизматики","Арсенал"],"answer":2,"steps":["Нумизматика изучает монеты, медали и связанные с ними предметы.","В фонд этого отдела вошла коллекция Александра Ланского."]},{"title":"Латинская буква","question":"В отделке интерьера Малого тронного зала использован вензель, составленный из латинской литеры…","choices":["E","P","A","N"],"answer":1,"steps":["Малый тронный зал посвящён Петру Великому.","Имя Petrus по-латыни начинается с P, поэтому эта литера использована в вензеле."],"figure":{"src":"assets/golden-fleece/2020/lessons/9-11/19.webp","alt":"Красный тронный зал с колоннами","width":178,"height":133}},{"title":"Работа Альтдорфера","question":"В этом секторе Отдела западноевропейского изобразительного искусства находится произведение А. Альтдорфера «Св. Иероним в пещере».","choices":["Сектор живописи XIII–XVII вв.","Сектор живописи ХХ-ХХ вв. и скульптуры","Сектор гравюр","Сектор рисунков"],"answer":2,"steps":["Изображение святого Иеронима выполнено в печатной графической технике.","Такие произведения хранятся в секторе гравюр."]},{"title":"Резьба по камню","question":"Этот шедевр эрмитажного собрания относится к искусству…","choices":["живописи","графики","круглой скульптуры","глиптики"],"answer":3,"steps":["Камею создают, вырезая выпуклое изображение на слоях камня разного цвета.","Искусство резных камней называется глиптикой."],"figure":{"src":"assets/golden-fleece/2020/lessons/9-11/21.webp","alt":"Камея с двумя профильными портретами","width":144,"height":178}},{"title":"Мадонна с книгой","question":"Кисти этого художника принадлежит Мадонна, изображенная с книгой, поступившая в Эрмитаж из коллекции Г. С. Строганова.","choices":["Фра Филиппо Липпи","С. Мартини","Фра Беато Анджелико","Рафаэль"],"answer":1,"steps":["Симоне Мартини изображал изящные фигуры на золочёном фоне и тщательно прописывал детали.","Его «Мадонна с книгой» пришла из коллекции Строганова."]},{"title":"Ранняя датированная работа","question":"Эрмитажная картина этого художника самая ранняя из датированных им работ.","choices":["Леонардо да Винчи","Эль Греко","Ф. Рибальта","Рафаэль"],"answer":2,"steps":["Франсиско Рибальта одним из ранних полотен написал «Пригвождение ко кресту».","Указанная на работе дата делает её важной для установления последовательности его произведений."],"figure":{"src":"assets/golden-fleece/2020/lessons/9-11/23.webp","alt":"Картина с группой людей у деревянного креста","width":140,"height":196}},{"title":"Поступление из Венеции","question":"Это полотно Тициана поступило в Эрмитаж в 1850 году из собрания К. Барбариго.","choices":["«Кающаяся Мария Магдалина»","«Мадонна Пезаро»","«Портрет молодой женщины»","«Бегство в Египет»"],"answer":0,"steps":["Тициан выбрал сюжет о покаянии Марии Магдалины и показал её с обращённым вверх взглядом.","Полотно поступило из собрания семьи Барбариго."]},{"title":"Встреча отца и сына","question":"Эта картина Рембрандта на сюжет новозаветной притчи поступила в Эрмитаж из парижского собрания А. д’Ансезена.","choices":["«Возвращение блудного сына»","«Отречение Петра»","«Артаксеркс, Аман и Эсфирь»","«Поклонение волхвов»"],"answer":0,"steps":["Пожилой человек принимает вернувшегося сына и кладёт руки ему на плечи.","Эта сцена из новозаветной притчи дала название картине Рембрандта."],"figure":{"src":"assets/golden-fleece/2020/lessons/9-11/25.webp","alt":"Пожилой человек кладёт руки на плечи коленопреклонённого","width":437,"height":560,"detailSrc":"assets/golden-fleece/2020/lessons/9-11/25-detail.webp"}},{"title":"Произведение после распродажи","question":"По итогам распродаж 20-х — 30-х гг. прошлого века Эрмитаж утратил последнее полотно этого живописца.","choices":["Рембрандт","Я. ван Эйк","П. П. Рубенс","Тициан"],"answer":1,"steps":["Картина Яна ван Эйка «Благовещение» раньше входила в собрание Эрмитажа.","Её продажа стала частью вывоза музейных ценностей в первой половине XX века."]},{"title":"Цветные мелки","question":"Это произведение французского художника Э. Дега выполнено в технике…","choices":["энкаустики","гуаши","пастели","темперы"],"answer":2,"steps":["Пастель состоит из пигмента, нанесённого сухими цветными мелками.","Эдгар Дега пользовался ею, чтобы передать мягкие переходы цвета и быстрые движения моделей."],"figure":{"src":"assets/golden-fleece/2020/lessons/9-11/27.webp","alt":"Две женские фигуры на картине","width":140,"height":184}},{"title":"Книга как искусство","question":"Двенадцать книг, оформленных этим художником, стали основой эрмитажной коллекции livre d’artiste (книги как произведения искусства).","choices":["С. Дали","А. Матисс","П. Пикассо","П. Боннар"],"answer":1,"steps":["Livre d’artiste объединяет авторский текст или подборку текстов с оригинальной графикой.","Анри Матисс оформлял такие книги, в том числе с собственными рисунками."]},{"title":"Квадрат в коллекции","question":"Вариант этой знаменитой картины К. С. Малевича поступил в коллекцию Эрмитажа в 2002 году.","choices":["«Чёрный квадрат»","«Красный квадрат»","«Скачет красная конница»","«Зимний пейзаж»"],"answer":0,"steps":["Малевич неоднократно возвращался к «Чёрному квадрату» и создал несколько его вариантов.","Один из них поступил в Эрмитаж в 2002 году."]},{"title":"Сюжет и авторство","question":"До поступления в Эрмитаж эта картина Джорджоне, находясь в коллекции А. Кроза, считалась работой кисти Рафаэля.","choices":["«Читающая мадонна»","«Лаура»","«Юдифь»","«Старуха» 30"],"answer":2,"steps":["Картина изображает Юдифь с мечом и отсылает к библейской истории.","В собрании Кроза её связывали с Рафаэлем, а современная атрибуция относит её к Джорджоне."],"figure":{"src":"assets/golden-fleece/2020/lessons/9-11/30.webp","alt":"Женская фигура с красной драпировкой","width":124,"height":280}},{"title":"Посещение картины Брюллова","question":"Эти строки А. С. Пушкина написаны под впечатлением от часовых у картины К. П. Брюллова в Эрмитаже.","choices":["«Живая власть для черни ненавистна»","«Ты им доволен ли, взыскательный художник?»","«Иные, лучшие, мне дороги права»","«Пускать не велено сюда простой народ?»"],"answer":3,"steps":["Пушкин откликнулся на показ «Последнего дня Помпеи» и ограничения для зрителей.","В вопросе о «простом народе» слышна его ирония над порядком допуска."]},{"title":"Сравнение Ольги","question":"Евгений Онегин сравнивает Ольгу Ларину с мадонной …","choices":["А. ван Дейка","Леонардо да Винчи","Рафаэля","фра Бартоломео"],"answer":0,"steps":["Онегин видит в облике Ольги сходство с изображением мадонны.","В стихах Пушкина назван фламандский мастер Антонис ван Дейк."]},{"title":"Строки о музее","question":"Этому русскому писателю принадлежат строки: «Произнесите слово Эрмитаж! В любом конце России — каждый уже слышал его».","choices":["Л. Н. Толстой","А. П. Чехов","Д. В. Григорович","И. С. Тургенев"],"answer":2,"steps":["Дмитрий Григорович написал «Прогулки по Эрмитажу», адресованные широкому читателю.","Призыв произнести имя музея подчёркивает, что о нём знали и далеко от Петербурга."]},{"title":"Картина в рассказе","question":"О картине этого художника «недалеко от рубенсовской залы» вспоминает один из героев рассказа Н. С. Лескова «Павлин».","choices":["А. ван Дейк","Я. Стен","Я. ван Эйк","Я. Йорданс"],"answer":2,"steps":["Герой Лескова вспоминает произведение старинной нидерландской живописи рядом с залами Рубенса.","В тексте это картина Яна ван Эйка."]},{"title":"Фигура над городом","question":"Где можно увидеть «латника в чёрном», о котором пишет в одном из стихотворений А. А. Блок?","choices":["В галерее 1812 года","В Рыцарском зале","На крыше Эрмитажа","На портике Нового Эрмитажа"],"answer":2,"steps":["На крыше дворца стоят фигуры, видимые снизу на фоне неба.","Одну из этих фигур строка Блока представляет как латника."]},{"title":"Поверенный в поэме","question":"О каком «присяжном поверенном» в Зимнем дворце пишет В. В. Маяковский в поэме «Хорошо»?","choices":["Ф. Н. Плевако","В. И. Ленин","А. Ф. Керенский","А. Ф. Кони"],"answer":2,"steps":["Керенский был юристом, а в 1917 году возглавлял Временное правительство.","Маяковский изображает его в Зимнем дворце, напоминая прежнюю профессию."]},{"title":"Солнце и живописная школа","question":"Этому поэту принадлежат строки о том, что «мрачнофламандскому Эрмитажу» не хватает пленэрной живописи и барбизонского солнца.","choices":["Н. С. Гумилев","О. Э. Мандельштам","А. А. Блок","В. В. Маяковский"],"answer":1,"steps":["Осип Мандельштам сопоставил тёмные тона старой фламандской живописи с работой художников на открытом воздухе.","Выражение о барбизонском солнце отсылает к пейзажистам Франции."]},{"title":"Город и память","question":"О своей неразлучности с городом на Неве, его зданиями, каналами и залами Эрмитажа в одной из поэм пишет…","choices":["А. А. Ахматова","М/И. Цветаева","А. А. Блок","0.3. Мандельштам"],"answer":0,"steps":["Анна Ахматова часто возвращалась в стихах к петербургским улицам, каналам и зданиям.","С ними и с Эрмитажем связана память о прожитых годах."]},{"title":"Вид издалека","question":"Это изображение Зимнего дворца создано А. А. Бенуа в 1939 году …","choices":["в эмиграции во Франции","во время написания путеводителя по Эрмитажу","в бытность директором Картинной галереи Эрмитажа","будучи в Париже с «Русскими сезонами» С. П. Дягилева"],"answer":0,"steps":["Бенуа жил во Франции и продолжал писать родной город по памяти и документам.","Вид Зимнего дворца 1939 года создан им в эмиграции."],"figure":{"src":"assets/golden-fleece/2020/lessons/9-11/39.webp","alt":"Улица зимой, люди идут мимо красного здания","width":185,"height":139}},{"title":"Мадонна в стихах","question":"И. А. Бродский в стихотворении «Иллюстрация» отразил свои впечатления о Мадонне…","choices":["Леонардо да Винчи","Л. Кранаха Старшего","Рафаэля","А. ван Дейка"],"answer":1,"steps":["Иосиф Бродский написал «Иллюстрацию» по впечатлению от музейной живописи.","В этом случае его внимание привлекла Мадонна Лукаса Кранаха Старшего."]},{"title":"Симметрия полотен","question":"Кисти этого художника принадлежат «две картины, зеркально симметричные друг другу», о которых пишет В. Б. Кривулин в стихотворении «Сон Иакова».","choices":["Р Кампен","С. Мартини","Б. Э. Мурильо","Караваджо"],"answer":2,"steps":["Две работы Мурильо связаны с библейской историей Иакова.","Поэт отмечает, что зритель может сравнить соответствующие позы и направления в двух композициях."]},{"title":"Фильм о картине","question":"Сценаристом фильма П. С. Когана о восприятии картины «Мадонна Литта» стал…","choices":["А. С. Кончаловский","Ф. С. Бондарчук","Г. Н. Данелия","С. А. Соловьёв"],"answer":3,"steps":["Фильм Петра Когана обращён к восприятию «Мадонны Литта» разными зрителями.","Сценарий написал Сергей Соловьёв."]},{"title":"Игровой фильм в музее","question":"Этот режиссёр снял художественный фильм об Эрмитаже.","choices":["Н. С. Михалков","А. Н. Сокуров","А. А. Тарковский","Э. А. Рязанов"],"answer":1,"steps":["Александр Сокуров снял «Русский ковчег», построенный как движение камеры по историческим залам.","Зритель проходит по Эрмитажу вместе с героями."]},{"title":"Штурм в киноэпопее","question":"Это событие показано в фильме-эпопее С. А. Герасимова «Тихий Дон».","choices":["Строительство Зимнего дворца","Пожар в Зимнем дворце в 1837 году","Обряд освящения Зимнего дворца","Штурм Зимнего дворца"],"answer":3,"steps":["Фильм «Тихий Дон» включает сцены революции 1917 года.","Среди них показан захват Зимнего дворца."]},{"title":"Земля как музей","question":"Этот учёный назвал нашу планету «Эрмитажем, несущемся в космическом пространстве».","choices":["К. Э. Циолковский","Д. С. Лихачёв","В. И. Вернадский","ЖИ. Алфёров"],"answer":1,"steps":["Дмитрий Лихачёв писал о необходимости сохранять культуру вместе с природой.","Сравнение планеты с Эрмитажем подчёркивает ценность того, что люди наследуют."]}]);
